package app.truemotion.vector;

import java.io.*;
import java.util.*;
import java.util.regex.*;
import java.util.zip.*;
import javax.xml.parsers.*;
import org.w3c.dom.*;

/** Modern ZIP FLA / packaged XFL reader. Unsupported artwork is reported explicitly. */
public final class VectorXfl {
    public static final class Result {public VectorDocument document;public final LinkedHashSet<String> warnings=new LinkedHashSet<String>();}
    final Result result=new Result();final Map<String,byte[]> files=new LinkedHashMap<String,byte[]>();final Map<String,VectorSymbol> names=new LinkedHashMap<String,VectorSymbol>();final Map<String,double[]> registration=new HashMap<String,double[]>();
    public static Result read(InputStream input)throws Exception{VectorXfl x=new VectorXfl();PushbackInputStream in=new PushbackInputStream(input,4);byte[] head=new byte[4];int got=in.read(head);if(got>0)in.unread(head,0,got);if(got<2||head[0]!='P'||head[1]!='K')throw new IOException("Only modern ZIP FLA / packaged XFL is supported; legacy binary FLA is not supported");ZipInputStream zip=new ZipInputStream(in);ZipEntry entry;long total=0;while((entry=zip.getNextEntry())!=null){String name=entry.getName().replace('\\','/');if(entry.isDirectory()||!name.toLowerCase(Locale.US).endsWith(".xml"))continue;ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[16384];int n;while((n=zip.read(buffer))>=0){if(n==0)continue;total+=n;if(total>32*1024*1024)throw new IOException("XFL XML exceeds 32 MB");bytes.write(buffer,0,n);}x.files.put(name,bytes.toByteArray());}String root=null;for(String path:x.files.keySet())if(path.endsWith("DOMDocument.xml")){root=path;break;}if(root==null)throw new IOException("DOMDocument.xml is missing");Element dom=parse(x.files.get(root));int w=(int)number(dom,"width",800),h=(int)number(dom,"height",600);double fps=number(dom,"frameRate",24);
        for(Map.Entry<String,byte[]> file:x.files.entrySet())if(file.getKey().contains("LIBRARY/")){Element e=parse(file.getValue());if(tag(e).equals("DOMSymbolItem")){String name=e.getAttribute("name");VectorDocument d=new VectorDocument(w,h,fps,1);VectorSymbol asset=new VectorSymbol(name,d);x.names.put(name,asset);}}
        for(Map.Entry<String,byte[]> file:x.files.entrySet())if(file.getKey().contains("LIBRARY/")){Element e=parse(file.getValue());if(tag(e).equals("DOMSymbolItem")){VectorSymbol asset=x.names.get(e.getAttribute("name"));if(asset!=null)asset.document=x.timeline(first(e,"timeline/DOMTimeline"),w,h,fps);}}
        Element main=first(dom,"timelines/DOMTimeline");if(main==null)throw new IOException("No XFL timeline");x.result.document=x.timeline(main,w,h,fps);for(VectorSymbol asset:x.names.values())x.result.document.symbols.put(asset.id,asset);for(VectorSymbol asset:x.names.values())asset.document.symbols=x.result.document.symbols;x.normalizeSymbols();x.result.document.validate();return x.result;}
    static Element parse(byte[] bytes)throws Exception{String scan=new String(bytes,"ISO-8859-1").replace("\u0000","").toUpperCase(Locale.US);if(scan.contains("<!DOCTYPE")||scan.contains("<!ENTITY"))throw new IOException("DTD and entity declarations are not allowed");DocumentBuilderFactory factory=DocumentBuilderFactory.newInstance();for(String feature:new String[]{"http://apache.org/xml/features/disallow-doctype-decl","http://xml.org/sax/features/external-general-entities","http://xml.org/sax/features/external-parameter-entities"})try{factory.setFeature(feature,feature.endsWith("disallow-doctype-decl"));}catch(ParserConfigurationException unsupported){/* Android Expat lacks these switches; preflight and resolver still reject entities. */}factory.setExpandEntityReferences(false);DocumentBuilder parser=factory.newDocumentBuilder();parser.setEntityResolver((publicId,systemId)->{throw new org.xml.sax.SAXException("External entities are not allowed");});return parser.parse(new ByteArrayInputStream(bytes)).getDocumentElement();}
    static String tag(Element e){String s=e.getTagName();return s.contains(":")?s.substring(s.indexOf(':')+1):s;}
    static List<Element> children(Element e,String tag){ArrayList<Element> out=new ArrayList<Element>();if(e==null)return out;for(Node n=e.getFirstChild();n!=null;n=n.getNextSibling())if(n instanceof Element&&(tag==null||tag((Element)n).equals(tag)))out.add((Element)n);return out;}
    static Element first(Element e,String path){for(String p:path.split("/")){List<Element> c=children(e,p);if(c.isEmpty())return null;e=c.get(0);}return e;}
    static double number(Element e,String key,double fallback){try{return e==null||!e.hasAttribute(key)?fallback:Double.parseDouble(e.getAttribute(key));}catch(Exception error){return fallback;}}
    static int color(Element e){String c=e.getAttribute("color");if(!c.matches("#[0-9a-fA-F]{6}"))return 0xff000000;int alpha=(int)Math.round(Math.max(0,Math.min(1,number(e,"alpha",1)))*255);return (alpha<<24)|(int)Long.parseLong(c.substring(1),16);}
    VectorDocument timeline(Element timeline,int w,int h,double fps)throws Exception{VectorDocument d=new VectorDocument(w,h,fps,1);d.tracks.clear();if(timeline==null)return d;List<Element> layers=children(first(timeline,"layers"),"DOMLayer");Collections.reverse(layers);int layerIndex=0;
        for(Element layer:layers){VectorDocument.Track t=new VectorDocument.Track(layer.getAttribute("name"));t.locked="true".equals(layer.getAttribute("locked"));t.visible=!"false".equals(layer.getAttribute("visible"))&&!"guide".equals(layer.getAttribute("layerType"));t.keys.clear();String type=layer.getAttribute("layerType");if(!type.isEmpty()&&!type.equals("normal")&&!type.equals("guide")&&!type.equals("folder"))result.warnings.add("Layer type: "+type);for(Element frame:children(first(layer,"frames"),"DOMFrame")){int index=(int)number(frame,"index",0),duration=Math.max(1,(int)number(frame,"duration",1));d.frames=Math.max(d.frames,index+duration);VectorDocument.Cel cel=new VectorDocument.Cel();int elementIndex=0;for(Element item:children(first(frame,"elements"),null))artwork(item,cel,identity(),"xfl-"+layerIndex+"-"+(elementIndex++));for(VectorDocument.Shape shape:cel.shapes)if(shape.isSymbol())shape.symbolStart=d.time(index);if("motion".equals(frame.getAttribute("tweenType"))||"shape".equals(frame.getAttribute("tweenType")))cel.tween=true;Element script=first(frame,"Actionscript/script");if(script!=null&&!script.getTextContent().trim().isEmpty())result.warnings.add("ActionScript retained as disabled source; execution is not supported");if(script!=null){d.script+=script.getTextContent()+"\n";d.scriptEnabled=false;}t.keys.put(index,cel);}if(!t.keys.containsKey(0))t.keys.put(0,new VectorDocument.Cel());for(Map.Entry<Integer,VectorDocument.Cel> key:t.keys.entrySet()){Integer next=t.keys.higherKey(key.getKey());if(key.getValue().tween&&(next==null||!VectorDocument.compatible(key.getValue(),t.keys.get(next)))){key.getValue().tween=false;result.warnings.add("A tween needs manual topology matching");}}d.tracks.add(t);layerIndex++;}
        if(d.tracks.isEmpty())d.tracks.add(new VectorDocument.Track("Layer 1"));return d;}
    static double[] identity(){return new double[]{1,0,0,1,0,0};}
    static double[] matrix(Element e){Element m=first(e,"matrix/Matrix");return m==null?identity():new double[]{number(m,"a",1),number(m,"b",0),number(m,"c",0),number(m,"d",1),number(m,"tx",0),number(m,"ty",0)};}
    static double[] multiply(double[] a,double[] b){return new double[]{a[0]*b[0]+a[2]*b[1],a[1]*b[0]+a[3]*b[1],a[0]*b[2]+a[2]*b[3],a[1]*b[2]+a[3]*b[3],a[0]*b[4]+a[2]*b[5]+a[4],a[1]*b[4]+a[3]*b[5]+a[5]};}
    void artwork(Element e,VectorDocument.Cel cel,double[] parent,String id)throws Exception{double[] m=multiply(parent,matrix(e));String kind=tag(e);if(kind.equals("DOMGroup")){int i=0;for(Element item:children(first(e,"members"),null))artwork(item,cel,m,id+"-"+(i++));return;}if(kind.equals("DOMSymbolInstance")){VectorSymbol asset=names.get(e.getAttribute("libraryItemName"));if(asset==null){result.warnings.add("Missing symbol: "+e.getAttribute("libraryItemName"));return;}VectorDocument.Shape s=new VectorDocument.Shape();s.id=id;s.name=e.hasAttribute("name")?e.getAttribute("name"):asset.name;s.symbol=asset.id;s.symbolOffset=(int)number(e,"firstFrame",0);s.symbolMode=e.getAttribute("loop").contains("single")?2:e.getAttribute("loop").contains("once")?1:0;transform(s,m);Element color=first(e,"color/Color");s.opacity=Math.max(0,Math.min(1,number(color,"alphaMultiplier",1)));cel.shapes.add(s);return;}
        if(kind.equals("DOMStaticText")||kind.equals("DOMDynamicText")){StringBuilder text=new StringBuilder();Element attrs=null;for(Element run:children(first(e,"textRuns"),"DOMTextRun")){Element characters=first(run,"characters");if(characters!=null)text.append(characters.getTextContent());if(attrs==null)attrs=first(run,"textAttrs/DOMTextAttrs");}if(text.length()==0)return;VectorDocument.Shape s=new VectorDocument.Shape();s.id=id;s.name=e.getAttribute("name");s.text=text.toString();s.fontSize=number(attrs,"size",18);s.fill=attrs==null?0xff000000:parseColor(attrs.getAttribute("fillColor"));s.strokeWidth=0;transform(s,m);double cx=number(e,"width",s.fontSize*text.length()*.6)/2,cy=number(e,"height",s.fontSize)/2;s.x+=m[0]*cx+m[2]*cy;s.y+=m[1]*cx+m[3]*cy;cel.shapes.add(s);result.warnings.add("Text fonts and layout require visual checking");return;}
        if(!kind.equals("DOMShape")){result.warnings.add("Unsupported artwork: "+kind);return;}
        Map<Integer,Integer> fills=new HashMap<Integer,Integer>();Map<Integer,double[]> strokes=new HashMap<Integer,double[]>();for(Element f:children(first(e,"fills"),"FillStyle")){Element solid=first(f,"SolidColor");if(solid==null){result.warnings.add("Gradient or bitmap fill is not supported");continue;}fills.put((int)number(f,"index",0),color(solid));}for(Element f:children(first(e,"strokes"),"StrokeStyle")){Element solid=first(f,"SolidStroke"),c=solid==null?null:first(solid,"fill/SolidColor");if(solid!=null&&c!=null)strokes.put((int)number(f,"index",0),new double[]{number(solid,"weight",1),color(c)});else result.warnings.add("Unsupported stroke style");}
        Map<Integer,List<VectorDocument.Shape>> fillPaths=new LinkedHashMap<Integer,List<VectorDocument.Shape>>();List<VectorDocument.Shape> strokePaths=new ArrayList<VectorDocument.Shape>();
        for(Element record:children(first(e,"edges"),"Edge")){int f0=(int)number(record,"fillStyle0",0),f1=(int)number(record,"fillStyle1",0),stroke=(int)number(record,"strokeStyle",0);for(VectorDocument.Shape segment:edge(record.getAttribute("edges"))){if(segment.nodes.size()<2)continue;if(f0!=f1){if(fills.containsKey(f0))add(fillPaths,f0,segment.copy());if(fills.containsKey(f1))add(fillPaths,f1,reverse(segment));}double[] style=strokes.get(stroke);if(style!=null){VectorDocument.Shape line=segment.copy();line.fill=0;line.strokeWidth=style[0]*Math.sqrt(Math.abs(m[0]*m[3]-m[1]*m[2]));line.stroke=(int)style[1];close(line);strokePaths.add(line);}}}
        int contour=0;for(Map.Entry<Integer,List<VectorDocument.Shape>> fill:fillPaths.entrySet()){List<VectorDocument.Shape> paths=join(fill.getValue());VectorDocument.Shape shape=new VectorDocument.Shape();shape.closed=true;shape.fill=fills.get(fill.getKey());shape.strokeWidth=0;for(VectorDocument.Shape path:paths){if(!close(path)){result.warnings.add("An open fill contour requires manual checking");continue;}if(shape.nodes.isEmpty())shape.nodes.addAll(path.nodes);else shape.contours.add(path.nodes);}if(shape.nodes.size()>1){shape.id=id+"-fill-"+(contour++);shape.name=e.getAttribute("name");bake(shape,m);cel.shapes.add(shape);}}
        for(VectorDocument.Shape line:strokePaths){line.id=id+"-stroke-"+(contour++);line.name=e.getAttribute("name");bake(line,m);cel.shapes.add(line);}
    }
    static void add(Map<Integer,List<VectorDocument.Shape>> map,int key,VectorDocument.Shape shape){List<VectorDocument.Shape> list=map.get(key);if(list==null){list=new ArrayList<VectorDocument.Shape>();map.put(key,list);}list.add(shape);}
    static void bake(VectorDocument.Shape s,double[] m){for(VectorDocument.Node n:s.allNodes()){double x=n.x,y=n.y,ix=n.ix,iy=n.iy,ox=n.ox,oy=n.oy;n.x=m[0]*x+m[2]*y+m[4];n.y=m[1]*x+m[3]*y+m[5];n.ix=m[0]*ix+m[2]*iy;n.iy=m[1]*ix+m[3]*iy;n.ox=m[0]*ox+m[2]*oy;n.oy=m[1]*ox+m[3]*oy;}s.recenter();}
    static VectorDocument.Shape reverse(VectorDocument.Shape s){VectorDocument.Shape out=s.copy();Collections.reverse(out.nodes);for(VectorDocument.Node n:out.nodes){double x=n.ix,y=n.iy;n.ix=n.ox;n.iy=n.oy;n.ox=x;n.oy=y;}return out;}
    static boolean same(VectorDocument.Node a,VectorDocument.Node b){return Math.abs(a.x-b.x)<.000001&&Math.abs(a.y-b.y)<.000001;}
    static boolean close(VectorDocument.Shape s){if(s.nodes.size()<2)return false;VectorDocument.Node a=s.nodes.get(0),b=s.nodes.get(s.nodes.size()-1);if(!same(a,b))return false;a.ix=b.ix;a.iy=b.iy;s.nodes.remove(s.nodes.size()-1);s.closed=true;return true;}
    static String point(VectorDocument.Node n){return Math.round(n.x*1000000)+","+Math.round(n.y*1000000);}
    static List<VectorDocument.Shape> join(List<VectorDocument.Shape> input){Map<String,ArrayDeque<VectorDocument.Shape>> starts=new LinkedHashMap<String,ArrayDeque<VectorDocument.Shape>>();for(VectorDocument.Shape s:input){String key=point(s.nodes.get(0));ArrayDeque<VectorDocument.Shape> list=starts.get(key);if(list==null){list=new ArrayDeque<VectorDocument.Shape>();starts.put(key,list);}list.add(s);}ArrayList<VectorDocument.Shape> result=new ArrayList<VectorDocument.Shape>();for(ArrayDeque<VectorDocument.Shape> queue:starts.values())while(!queue.isEmpty()){VectorDocument.Shape s=queue.removeFirst();VectorDocument.Node first=s.nodes.get(0),last=s.nodes.get(s.nodes.size()-1);int remaining=input.size();while(!same(first,last)&&remaining-->0){ArrayDeque<VectorDocument.Shape> next=starts.get(point(last));if(next==null||next.isEmpty())break;VectorDocument.Shape tail=next.removeFirst();VectorDocument.Node head=tail.nodes.get(0);last.ox=head.ox;last.oy=head.oy;for(int i=1;i<tail.nodes.size();i++)s.nodes.add(tail.nodes.get(i));last=s.nodes.get(s.nodes.size()-1);}result.add(s);}return result;}
    void normalizeSymbols(){for(VectorSymbol asset:names.values())bounds(asset.id,new HashSet<String>(),0);for(VectorSymbol asset:names.values()){double[] b=registration.get(asset.id);shift(asset.document,b[0],b[1]);asset.document.width=Math.max(1,(int)Math.ceil(b[2]-b[0]));asset.document.height=Math.max(1,(int)Math.ceil(b[3]-b[1]));}shift(result.document,0,0);}
    double[] bounds(String id,Set<String> active,int depth){double[] known=registration.get(id);if(known!=null)return known;if(depth>32||!active.add(id))throw new IllegalArgumentException("Cyclic or too deep symbol library");VectorSymbol asset=result.document.symbols.get(id);double[] out={Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY,Double.NEGATIVE_INFINITY,Double.NEGATIVE_INFINITY};for(VectorDocument.Track t:asset.document.tracks)if(t.visible)for(VectorDocument.Cel c:t.keys.values())for(VectorDocument.Shape s:c.shapes){double[] b=s.isSymbol()?bounds(s.symbol,active,depth+1):s.bounds();double pad=s.isSymbol()?0:s.strokeWidth/2;for(double[] xy:new double[][]{{b[0]-pad,b[1]-pad},{b[2]+pad,b[1]-pad},{b[2]+pad,b[3]+pad},{b[0]-pad,b[3]+pad}}){double[] p=s.world(xy[0],xy[1]);out[0]=Math.min(out[0],p[0]);out[1]=Math.min(out[1],p[1]);out[2]=Math.max(out[2],p[0]);out[3]=Math.max(out[3],p[1]);}}active.remove(id);if(!Double.isFinite(out[0]))out=new double[]{0,0,1,1};out[0]=Math.floor(out[0])-1;out[1]=Math.floor(out[1])-1;out[2]=Math.ceil(out[2])+1;out[3]=Math.ceil(out[3])+1;registration.put(id,out);return out;}
    void shift(VectorDocument d,double x,double y){for(VectorDocument.Track t:d.tracks)for(VectorDocument.Cel c:t.keys.values())for(VectorDocument.Shape s:c.shapes){if(s.isSymbol()){double[] b=registration.get(s.symbol),v=s.world((b[0]+b[2])/2,(b[1]+b[3])/2);s.x=v[0];s.y=v[1];}s.x-=x;s.y-=y;}}
    static int parseColor(String c){try{return 0xff000000|(int)Long.parseLong(c.replace("#",""),16);}catch(Exception e){return 0xff000000;}}
    void transform(VectorDocument.Shape s,double[] m){s.x=m[4];s.y=m[5];s.sx=Math.hypot(m[0],m[1]);s.sy=(m[0]*m[3]-m[1]*m[2])/Math.max(.00001,s.sx);s.angle=Math.toDegrees(Math.atan2(m[1],m[0]));if(Math.abs(m[0]*m[2]+m[1]*m[3])>.001)result.warnings.add("Sheared symbol/text transform requires manual checking");}
    static double coordinate(String value){if(value.startsWith("#")){String[] parts=value.substring(1).split("\\.");long n=Long.parseLong(parts[0],16);if(n>=0x800000L)n-=0x1000000L;double fractional=parts.length>1?Long.parseLong(parts[1],16)/Math.pow(16,parts[1].length()):0;return (n+fractional)/20;}return Double.parseDouble(value)/20;}
    static List<VectorDocument.Shape> edge(String source)throws IOException{Matcher matcher=Pattern.compile("[!|/\\[\\]]|S[0-7]|#[0-9a-fA-F]+(?:\\.[0-9a-fA-F]+)?|[-+]?(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)").matcher(source);ArrayList<String> tokens=new ArrayList<String>();int previous=0;while(matcher.find()){if(!source.substring(previous,matcher.start()).trim().isEmpty())throw new IOException("Unknown XFL edge syntax");tokens.add(matcher.group());previous=matcher.end();}if(!source.substring(previous).trim().isEmpty())throw new IOException("Unknown XFL edge syntax");ArrayList<VectorDocument.Shape> paths=new ArrayList<VectorDocument.Shape>();VectorDocument.Shape current=null;int at=0;try{while(at<tokens.size()){String op=tokens.get(at++);if(op.startsWith("S"))continue;if(op.equals("!")){VectorDocument.Node move=new VectorDocument.Node(coordinate(tokens.get(at++)),coordinate(tokens.get(at++)));if(current!=null&&same(current.nodes.get(current.nodes.size()-1),move))continue;current=new VectorDocument.Shape();current.nodes.add(move);paths.add(current);}else if(op.equals("|")||op.equals("/")){if(current==null)throw new IOException("XFL line before move");current.nodes.add(new VectorDocument.Node(coordinate(tokens.get(at++)),coordinate(tokens.get(at++))));}else if(op.equals("[")||op.equals("]")){if(current==null)throw new IOException("XFL curve before move");double x=coordinate(tokens.get(at++)),y=coordinate(tokens.get(at++));VectorDocument.Node next=new VectorDocument.Node(coordinate(tokens.get(at++)),coordinate(tokens.get(at++))),prev=current.nodes.get(current.nodes.size()-1);prev.ox=(x-prev.x)*2/3;prev.oy=(y-prev.y)*2/3;next.ix=(x-next.x)*2/3;next.iy=(y-next.y)*2/3;current.nodes.add(next);}else throw new IOException("Unsupported XFL edge command: "+op);}}catch(IndexOutOfBoundsException e){throw new IOException("Truncated XFL edge",e);}return paths;}
}
